int fd_a = 3, fd_b = 4;
fd_set rfds, wfds;
struct timeval tv = {5, 0}; // 5 sec timeout

FD_ZERO(&rfds);
FD_SET(fd_a, &rfds);        // Monitor fd_a for read
FD_SET(fd_b, &wfds);        // Monitor fd_b for write

int nfds = (fd_a > fd_b ? fd_a : fd_b) + 1;

// Monitor (readfds, writefds, exceptfds, timeout)
int ret = select(nfds, &rfds, &wfds, NULL, &tv);

if (ret > 0) {
    if (FD_ISSET(fd_a, &rfds)) {
        // fd_a is ready to read
    }
} else if (ret == 0) {
    // Timeout occurred
}
